CREATE OR REPLACE VIEW agriculture_demo.v_extension_followups AS SELECT v.visit_ref,f.farm_token,a.area_code,f.primary_crop,f.season_code,v.visit_at,v.topic,v.finding_summary,v.follow_up_due FROM agriculture_demo.extension_visits v JOIN agriculture_demo.farm_refs f USING(farm_id) JOIN agriculture_demo.service_areas a USING(area_id) WHERE f.is_active AND v.outcome='follow_up';
CREATE OR REPLACE VIEW agriculture_demo.v_delivery_fulfilment AS SELECT d.delivery_ref,f.farm_token,a.area_code,d.input_type,d.input_label,d.planned_qty,d.dispatched_qty,d.received_qty,d.planned_qty-d.dispatched_qty AS not_dispatched_qty,d.dispatched_qty-d.received_qty AS receipt_variance_qty,d.unit_code,d.status,d.dispatch_ref,d.receipt_ref FROM agriculture_demo.input_deliveries d JOIN agriculture_demo.farm_refs f USING(farm_id) JOIN agriculture_demo.service_areas a USING(area_id);
CREATE OR REPLACE VIEW agriculture_demo.v_delivery_exceptions AS SELECT * FROM agriculture_demo.v_delivery_fulfilment WHERE status='disputed' OR(status='received' AND received_qty<>planned_qty);